/* DMA buffer sizes: circular buffers that are processed half by half (ping-pong) */
#define I2S_HALF_FRAMES         256U                         /* stereo frames per half-buffer */
#define I2S_HALF_SAMPLES        (I2S_HALF_FRAMES * 2U)       /* L+R samples per half-buffer */
#define I2S_BUFFER_SAMPLES      (I2S_HALF_SAMPLES * 2U)      /* both halves */

/* Gain per source in dB (left and right), the output is saturated */
#define MIC_GAIN_DB             2.0f        /* PCM1808, SAI1 A */
#define ADC_GAIN_DB             2.0f        /* analog mics, ADC3 + ADC2 */
/* PCM1808 (SAI1 A: PE2 SCKI, PE4 LRCK, PE5 BCK, PE6 DOUT): audio source, equalized and played.
 * Analog mics (left PF6 / ADC3_INP8, right PA3 / ADC2_INP15): measurement microphones of the room equalizer.
 * B1 (PC13): short press = room adaptation run / freeze (LD2 lit = running), hold 1 s = room equalizer on / off
 *            incl. the manual filters (LD3 lit = off). The PCM1808 / mic correction filters always stay on.
 * Serial terminal (USART3, 115200): see Gain_HandleUart(). */
#define MIC_SRC_I2S             0U       /* PCM1808: source, played */
#define MIC_SRC_ADC             1U       /* analog mics: only measured */
#define MIC_SRC_COUNT           2U
#define ADC_HALF_SAMPLES        I2S_HALF_FRAMES              /* per ADC channel, same block length as SAI */
/* Master output volume in dB, applied after the per-source gains (DAC full scale = 2.1 Vrms per channel) */
#define OUTPUT_GAIN_DB          -5.0f
/* DAC output: I2S1 (PB3 BCK, PA15 LRCK, PB5 DIN), plain stereo: left channel on OUTL, right channel on OUTR. */
#define hi2sOut                 hi2s1
/* Recording marker: a short pulse on both outputs (after the room equalizer, independent of gain and mute) when the
 * adaptation is started (1 pulse) or frozen (2 pulses). A start is delayed until the marker has left the mic frames. */
#define MARKER_FREQ_HZ          19000.0f
#define MARKER_AMP              0.9f                         /* peak, fraction of full scale */
#define MARKER_BURST_MS         5U                           /* length of one pulse and of the gap between two pulses */
#define MARKER_RAMP_US          500U                         /* fade in / out */
#define MARKER_SETTLE_MS        400U                         /* delay of the adaptation start after the marker */
#define MARKER_BURST_SAMPLES    ((uint32_t)(ROOMEQ_FS_HZ * MARKER_BURST_MS / 1000.0))
#define MARKER_RAMP_SAMPLES     ((uint32_t)(ROOMEQ_FS_HZ * MARKER_RAMP_US / 1000000.0))
/* USER CODE END PD */

