/* USER CODE BEGIN PV */
/* Buffer filled by the PCM1808 (SAI RX DMA), stereo interleaved L,R */
int16_t micRxBuffer[I2S_BUFFER_SAMPLES];

/* Buffer read by the Speaker/DAC (I2S TX DMA), stereo interleaved L,R */
int16_t i2sTxBuffer[I2S_BUFFER_SAMPLES];

volatile uint32_t rxCount = 0, txCount = 0;
volatile int16_t  micPeak = 0;              /* peak |sample| of last block, for UART debug */
volatile int16_t  rawMin[2], rawMax[2];     /* raw SAI data per slot (L,R) of last block */
volatile uint32_t saiSr = 0;                /* SAI1 Block A status register, sticky errors */

/* Analog mics: channel 0 = ADC3 / PF6 (left), channel 1 = ADC2 / PA3 (right).
 * ADC3 is served by the BDMA, which can only reach SRAM4 -> .sram4 section (see linker script).
 * ADC2 is served by DMA1 (stream 3), which reaches the normal AXI SRAM. */
__attribute__((section(".sram4"), aligned(32))) uint16_t adcRxBuffer[ADC_HALF_SAMPLES * 2U];
__attribute__((aligned(32))) uint16_t adc2RxBuffer[ADC_HALF_SAMPLES * 2U];
/* The two ADCs deliver their halves in separate callbacks: collect them here, process when both are in */
static int16_t  adcPcm[2][2][ADC_HALF_SAMPLES];     /* [half][channel][sample], signed */
static uint8_t  adcReady[2];                        /* per half: bit 0 = ADC3 in, bit 1 = ADC2 in */
volatile uint32_t adcCount = 0;
volatile uint16_t adcMin[2], adcMax[2];             /* raw ADC range of last block per channel, for UART debug */


static uint32_t lastPrint = 0;
/* Per source (index = MIC_SRC_xxx) */
static int32_t        srcDc[MIC_SRC_COUNT][2];           /* DC blocker states per channel, Q8 */
static float          srcGain[MIC_SRC_COUNT];            /* linear gain, from *_GAIN_DB at startup */
static float          outGain = 1.0f;                    /* master volume, from OUTPUT_GAIN_DB */
static volatile float lvlSumSq[MIC_SRC_COUNT][2];        /* sum of squares BEFORE gain per channel, for the level meter */
static volatile uint32_t lvlCount[MIC_SRC_COUNT];

/* Frequency-response correction: one biquad cascade per source and channel (coefficients from Tools/EQ_to_BIQUAD.py).
 * The PCM1808 cascades are applied in Audio_ProcessBlock(), the ADC (mic) cascades in the analysis of room_eq.c.
 * Double precision: the low-frequency sections have poles very close to the unit circle. */
static const struct { const MicEqBiquad *bq; uint32_t n; } eqTable[MIC_SRC_COUNT][2] = {
    { { micEq_pcmL, MIC_EQ_PCML_N }, { micEq_pcmR, MIC_EQ_PCMR_N } },    /* MIC_SRC_I2S */
    { { micEq_adcL, MIC_EQ_ADCL_N }, { micEq_adcR, MIC_EQ_ADCR_N } },    /* MIC_SRC_ADC */
};
/* Coefficients and states live in DTCM (zero wait states; the data cache is off, so flash / AXI SRAM accesses are slow).
 * The coefficients are copied from flash in Eq_Init(). */
__attribute__((section(".dtcm"), aligned(8))) static MicEqBiquad eqCoef[MIC_SRC_COUNT][2][MIC_EQ_MAX_SECTIONS];
__attribute__((section(".dtcm"), aligned(8))) static double      eqState[MIC_SRC_COUNT][2][MIC_EQ_MAX_SECTIONS][2];   /* transposed DF2: z1, z2 */
volatile uint32_t procCyclesMax = 0;    /* worst Audio_ProcessBlock time, PCM1808 path incl. room equalizer, CPU cycles */
volatile uint32_t procMicCyclesMax = 0; /* worst time of the mic path */
volatile uint32_t pollCyclesMax = 0;    /* worst room analysis frame (main loop) */
static volatile uint8_t eqReset[MIC_SRC_COUNT];   /* start the correction filters of a source from zero state */

/* Room equalizer in the audio path: up to ROOMEQ_MAX_FILTERS peaking biquads, same coefficients for L and R. The coefficients
 * are designed by room_eq.c in the main loop and copied here by the audio interrupt.
 * Single precision for speed (the Cortex-M7 FPU pipelines float but not double); the float noise stays below about -90 dB. */
typedef struct { float b0, b1, b2, a1, a2; } RoomBqF;
__attribute__((section(".dtcm"), aligned(8))) static RoomBqF roomBq[ROOMEQ_MAX_FILTERS];
__attribute__((section(".dtcm"), aligned(8))) static float   roomState[2][ROOMEQ_MAX_FILTERS][2];
/* The lowest sections (poles very close to the unit circle) stay in double precision: float noise there is about 15 dB higher. */
#define ROOM_DBL_FREQ_HZ        120.0
#define ROOM_DBL_MAX            4U
__attribute__((section(".dtcm"), aligned(8))) static RoomEqBiquad roomBqD[ROOM_DBL_MAX];
__attribute__((section(".dtcm"), aligned(8))) static double       roomStateD[2][ROOM_DBL_MAX][2];
static uint32_t         roomND = 0;
static uint32_t         roomN = 0;
static uint32_t         roomSeq = 0xFFFFFFFFu;
/* Manual peaking filters (keys k/x/X/j/J/l/L/o) for narrow room modes that the band equalizer cannot resolve.
 * Same stage as the adaptive equalizer (double precision, both channels), switched with 'q' together with it. */
#define ROOM_MANUAL_MAX         3U
typedef struct { uint8_t on; float freq, gainDb, q; } ManualPk;
static ManualPk manualPk[ROOM_MANUAL_MAX] = { { 1, 84.5f, 0.0f, 6.0f }, { 0, 50.0f, 0.0f, 6.0f }, { 0, 120.0f, 0.0f, 6.0f } };
static uint32_t manualSel = 0;
static RoomEqBiquad manualBuf[2][ROOM_MANUAL_MAX];            /* main loop writes the idle buffer, then flips */
static uint32_t     manualCount[2];
static volatile uint32_t manualCur = 0, manualSeq = 0;
__attribute__((section(".dtcm"), aligned(8))) static RoomEqBiquad manBq[ROOM_MANUAL_MAX];
__attribute__((section(".dtcm"), aligned(8))) static double       manState[2][ROOM_MANUAL_MAX][2];
static uint32_t         manN = 0, manSeqSeen = 0xFFFFFFFFu;
static volatile uint8_t roomMute = 0;   /* output muted while the mics measure their noise floor */
static uint32_t         muteUntil = 0;
static volatile uint8_t roomShed = 0;   /* set when a block took too long: the room equalizer was switched off */
static volatile uint32_t shedCycles = 0;
static volatile uint8_t errSai = 0, errAdc = 0, errI2s = 0;   /* set by the error callbacks, printed in the main loop */
static volatile uint8_t roomReset = 0;
static volatile uint8_t markerReq = 0;  /* number of marker pulses requested by the main loop (1 = adaptation started, 2 = frozen) */
static uint8_t          markerBursts = 0;                    /* owned by the audio interrupt */
static uint32_t         markerPos = 0;
static float            markerPhase = 0.0f;
static uint8_t          adaptPending = 0;                    /* start requested, waiting for the marker to fade out */
static uint32_t         adaptStartAt = 0;
static volatile uint8_t roomBypass = 0; /* 1 = room equalizer off (B1 hold / 'q' / overload protection), LD3 red lit */
/* USER CODE END PV */

