/**
 * @brief  Return the half of i2sTxBuffer that the I2S DMA is NOT playing right now.
 *         SAI1, I2S and TIM6 (ADC trigger) share PLL1, so every source delivers one block per TX half-buffer.
 *         The sources are started in the middle of a TX half (Audio_WaitTxMidHalf), which leaves half a block of margin.
 */
static int16_t *Audio_TxHalfToFill(void)
{
    uint32_t txRemaining = __HAL_DMA_GET_COUNTER(hi2sOut.hdmatx);        /* counts down */
    return (txRemaining > I2S_HALF_SAMPLES) ? &i2sTxBuffer[I2S_HALF_SAMPLES]  /* TX plays half 0 */
                                            : &i2sTxBuffer[0];                /* TX plays half 1 */
}

static inline __attribute__((always_inline)) float Audio_Clip(float v)
{
    if (v >  32767.0f) return  32767.0f;
    if (v < -32768.0f) return -32768.0f;
    return v;
}

/* next sample of the marker (burst, gap, burst ...; 0 when idle), called once per output frame while markerBursts != 0 */
static float Marker_Next(void)
{
    const uint32_t B = MARKER_BURST_SAMPLES, R = MARKER_RAMP_SAMPLES;
    if (markerPos >= (2U * markerBursts - 1U) * B)
    {
        markerBursts = 0U;
        return 0.0f;
    }
    const uint32_t o = markerPos % (2U * B);                 /* position inside burst + gap */
    markerPos++;
    if (o >= B) return 0.0f;                                 /* gap */
    float env = 1.0f;
    if (o < R)                env = (float)o / (float)R;
    else if (o >= B - R)      env = (float)(B - 1U - o) / (float)R;
    markerPhase += 6.2831853f * MARKER_FREQ_HZ / (float)ROOMEQ_FS_HZ;
    if (markerPhase >= 6.2831853f) markerPhase -= 6.2831853f;
    return MARKER_AMP * 32767.0f * env * sinf(markerPhase);
}

/**
 * @brief  Process one block (I2S_HALF_FRAMES samples) of a stereo input: DC blocker, level measurement and
 *         the correction filters (frequency response of the PCM1808; the analog mics are corrected in the analysis).
 *         - MIC_SRC_I2S (PCM1808) is the audio source: room equalizer, gain, saturation and output to
 *           the I2S TX buffer. The mono sum of the corrected PCM1808 signal BEFORE the room equalizer is the reference of the room analysis.
 *         - MIC_SRC_ADC (analog mics) are the measurement microphones: they only feed the room analysis.
 * @param  source  MIC_SRC_xxx
 * @param  dst     TX half from Audio_TxHalfToFill(), taken at callback ENTRY (NULL for the mics)
 * @param  srcL    first left sample (mic 1 / PF6)
 * @param  srcR    first right sample (mic 2 / PA3)
 * @param  stride  distance between samples of one channel (2 = interleaved stereo, 1 = separate buffers)
 */
__attribute__((optimize("O2")))
static void Audio_ProcessBlock(uint32_t source, int16_t *dst,
                               const int16_t *srcL, const int16_t *srcR, uint32_t stride)
{
    const uint32_t t0    = DWT->CYCCNT;
    const uint8_t  isOut = (source == MIC_SRC_I2S);
    const float    g     = roomMute ? 0.0f : srcGain[source] * outGain;
    int32_t        dcL   = srcDc[source][0];
    int32_t        dcR   = srcDc[source][1];
    float          sumL  = 0.0f;
    float          sumR  = 0.0f;
    int16_t        peak  = 0;
    int16_t        blkL[I2S_HALF_FRAMES], blkR[I2S_HALF_FRAMES];    /* mic samples for the analysis */

    /* The PCM1808 correction runs here; the analog mics are corrected in the frequency domain in room_eq.c */
    const MicEqBiquad *bqL = eqCoef[source][0];
    const MicEqBiquad *bqR = eqCoef[source][1];
    const uint32_t     nL  = isOut ? eqTable[source][0].n : 0U;
    const uint32_t     nR  = isOut ? eqTable[source][1].n : 0U;
    double (*zL)[2]        = eqState[source][0];
    double (*zR)[2]        = eqState[source][1];

    if (eqReset[source])
    {
        memset(eqState[source], 0, sizeof(eqState[source]));
        eqReset[source] = 0U;
    }

    const RoomBqF *rbq = roomBq;
    uint32_t       rn  = 0U, mn = 0U;
    double (*mdL)[2]   = manState[0];
    double (*mdR)[2]   = manState[1];
    float (*rzL)[2]    = roomState[0];
    float (*rzR)[2]    = roomState[1];
    double (*rdL)[2]   = roomStateD[0];
    double (*rdR)[2]   = roomStateD[1];
    if (isOut)
    {
        const uint32_t seq = RoomEq_CoefSeq();                 /* new room equalizer from the main loop? */
        if (seq != roomSeq)
        {
            const RoomEqCoefs *c = RoomEq_Coefs();
            roomN  = c->n;
            roomND = 0;
            while (roomND < c->n && roomND < ROOM_DBL_MAX && RoomEq_FilterFreq(roomND) < ROOM_DBL_FREQ_HZ)
            {
                roomBqD[roomND] = c->bq[roomND];
                roomND++;
            }
            for (uint32_t k = 0; k < c->n; k++)
            {
                roomBq[k].b0 = (float)c->bq[k].b0;  roomBq[k].b1 = (float)c->bq[k].b1;  roomBq[k].b2 = (float)c->bq[k].b2;
                roomBq[k].a1 = (float)c->bq[k].a1;  roomBq[k].a2 = (float)c->bq[k].a2;
            }
            roomSeq = seq;
        }
        if (markerReq)                                          /* marker requested by the main loop */
        {
            markerBursts = markerReq;
            markerReq    = 0U;
            markerPos    = 0U;
            markerPhase  = 0.0f;
        }
        const uint32_t msq = manualSeq;
        if (msq != manSeqSeen)
        {
            const uint32_t cur = manualCur;
            manN = manualCount[cur];
            for (uint32_t k = 0; k < manN; k++) manBq[k] = manualBuf[cur][k];
            manSeqSeen = msq;
        }
        if (roomReset)
        {
            memset(roomState, 0, sizeof(roomState));
            memset(roomStateD, 0, sizeof(roomStateD));
            memset(manState, 0, sizeof(manState));
            roomReset = 0U;
        }
        rn = roomBypass ? 0U : roomN;
        mn = roomBypass ? 0U : manN;
    }

    for (uint32_t i = 0; i < I2S_HALF_FRAMES; i++)
    {
        int32_t xl = srcL[i * stride];
        int32_t xr = srcR[i * stride];

        /* one-pole DC blocker: dc += (x - dc) / 256 */
        dcL += ((xl << 8) - dcL) >> 8;
        dcR += ((xr << 8) - dcR) >> 8;
        float dl = (float)(xl - (dcL >> 8));
        float dr = (float)(xr - (dcR >> 8));
        sumL += dl * dl;
        sumR += dr * dr;

        /* frequency-response correction (the level meter above stays uncorrected) */
        double ql = (double)dl;
        double qr = (double)dr;
        for (uint32_t k = 0; k < nL; k++)
        {
            double y = bqL[k].b0 * ql + zL[k][0];
            zL[k][0] = bqL[k].b1 * ql - bqL[k].a1 * y + zL[k][1];
            zL[k][1] = bqL[k].b2 * ql - bqL[k].a2 * y;
            ql = y;
        }
        for (uint32_t k = 0; k < nR; k++)
        {
            double y = bqR[k].b0 * qr + zR[k][0];
            zR[k][0] = bqR[k].b1 * qr - bqR[k].a1 * y + zR[k][1];
            zR[k][1] = bqR[k].b2 * qr - bqR[k].a2 * y;
            qr = y;
        }

        if (isOut)
        {
            /* reference of the room analysis: mono sum of the corrected input before the equalizer, with the output gain (0 while muted) */
            blkL[i] = (int16_t)Audio_Clip((float)(0.5 * (ql + qr)) * g);
            /* room equalizer: the same filters on both channels */
            const uint32_t nd = (rn < roomND) ? rn : roomND;
            for (uint32_t k = 0; k < nd; k++)                      /* lowest sections in double precision */
            {
                double y = roomBqD[k].b0 * ql + rdL[k][0];
                rdL[k][0] = roomBqD[k].b1 * ql - roomBqD[k].a1 * y + rdL[k][1];
                rdL[k][1] = roomBqD[k].b2 * ql - roomBqD[k].a2 * y;
                ql = y;
                y = roomBqD[k].b0 * qr + rdR[k][0];
                rdR[k][0] = roomBqD[k].b1 * qr - roomBqD[k].a1 * y + rdR[k][1];
                rdR[k][1] = roomBqD[k].b2 * qr - roomBqD[k].a2 * y;
                qr = y;
            }
            for (uint32_t k = 0; k < mn; k++)                      /* manual peaking filters, double precision */
            {
                double y = manBq[k].b0 * ql + mdL[k][0];
                mdL[k][0] = manBq[k].b1 * ql - manBq[k].a1 * y + mdL[k][1];
                mdL[k][1] = manBq[k].b2 * ql - manBq[k].a2 * y;
                ql = y;
                y = manBq[k].b0 * qr + mdR[k][0];
                mdR[k][0] = manBq[k].b1 * qr - manBq[k].a1 * y + mdR[k][1];
                mdR[k][1] = manBq[k].b2 * qr - manBq[k].a2 * y;
                qr = y;
            }
            float fl = (float)ql, fr = (float)qr;
            for (uint32_t k = nd; k < rn; k++)
            {
                const float b0 = rbq[k].b0, b1 = rbq[k].b1, b2 = rbq[k].b2, a1 = rbq[k].a1, a2 = rbq[k].a2;
                const float yl_ = b0 * fl + rzL[k][0];
                const float yr_ = b0 * fr + rzR[k][0];
                rzL[k][0] = b1 * fl - a1 * yl_ + rzL[k][1];
                rzR[k][0] = b1 * fr - a1 * yr_ + rzR[k][1];
                rzL[k][1] = b2 * fl - a2 * yl_;
                rzR[k][1] = b2 * fr - a2 * yr_;
                fl = yl_;
                fr = yr_;
            }

            if (!(fl > -1.0e6f && fl < 1.0e6f && fr > -1.0e6f && fr < 1.0e6f))      /* NaN / Inf / runaway */
            {
                memset(roomState, 0, sizeof(roomState));
                memset(roomStateD, 0, sizeof(roomStateD));
                memset(manState, 0, sizeof(manState));
                fl = (float)ql;
                fr = (float)qr;
            }

            const float mk = markerBursts ? Marker_Next() : 0.0f;     /* recording marker, after the equalizer, not scaled by g */
            int16_t yl = (int16_t)Audio_Clip(fl * g + mk);
            int16_t yr = (int16_t)Audio_Clip(fr * g + mk);
            dst[2U * i]      = yl;         /* left  */
            dst[2U * i + 1U] = yr;         /* right */

            int16_t al = (int16_t)((yl < 0) ? -yl : yl);
            int16_t ar = (int16_t)((yr < 0) ? -yr : yr);
            if (al > peak) peak = al;
            if (ar > peak) peak = ar;
        }
        else
        {
            blkL[i] = (int16_t)Audio_Clip((float)ql);      /* corrected mic signal, no gain */
            blkR[i] = (int16_t)Audio_Clip((float)qr);
        }
    }
    srcDc[source][0] = dcL;
    srcDc[source][1] = dcR;

    lvlSumSq[source][0] += sumL;
    lvlSumSq[source][1] += sumR;
    lvlCount[source]    += I2S_HALF_FRAMES;

    if (isOut)
    {
        micPeak = peak;
        RoomEq_PushRef(blkL, I2S_HALF_FRAMES);             /* reference: filled before the equalizer in the sample loop above */


        uint32_t dt = DWT->CYCCNT - t0;
        if (dt > procCyclesMax) procCyclesMax = dt;

        /* load protection: a call that alone takes more than 75 % of the block time starves the main loop,
         * so the room equalizer is switched off and reported */
        if ((dt > (SystemCoreClock / 44100U) * I2S_HALF_FRAMES * 3U / 4U) && !roomBypass)
        {
            roomBypass = 1U;
            roomReset  = 1U;
            shedCycles = dt;
            roomShed   = 1U;
        }
    }
    else
    {
        RoomEq_PushMic(0U, blkL, I2S_HALF_FRAMES);
        RoomEq_PushMic(1U, blkR, I2S_HALF_FRAMES);

        uint32_t dt = DWT->CYCCNT - t0;
        if (dt > procMicCyclesMax) procMicCyclesMax = dt;
    }
}

/* One finished half of micRxBuffer (PCM1808, stereo slots: slot 0 = left, slot 1 = right) */
static void Audio_SaiBlock(const int16_t *src)
{
    int16_t *dst = Audio_TxHalfToFill();

    /* raw data, both slots, before DC blocker / gain */
    for (uint32_t ch = 0; ch < 2U; ch++)
    {
        int16_t mn = INT16_MAX, mx = INT16_MIN;
        for (uint32_t i = 0; i < I2S_HALF_FRAMES; i++)
        {
            int16_t v = src[2U * i + ch];
            if (v < mn) mn = v;
            if (v > mx) mx = v;
        }
        rawMin[ch] = mn;
        rawMax[ch] = mx;
    }
    saiSr |= SAI1_Block_A->SR;
    rxCount++;

    Audio_ProcessBlock(MIC_SRC_I2S, dst, &src[0], &src[1], 2U);
}

/**
 * @brief  One finished half of an ADC buffer (unsigned 16-bit mono). The left (ADC3) and
 *         right (ADC2) mic are triggered by the same TIM6 event but report through separate
 *         DMA callbacks; the block is processed as soon as both halves of the same index are in.
 * @param  ch    0 = ADC3 / PF6 (left), 1 = ADC2 / PA3 (right)
 * @param  half  0 = first half of the DMA buffer, 1 = second half
 */
static void Audio_AdcBlock(uint32_t ch, uint32_t half, const uint16_t *src)
{
    int16_t  *pcm = adcPcm[half][ch];
    uint16_t  mn = UINT16_MAX, mx = 0;

    for (uint32_t i = 0; i < ADC_HALF_SAMPLES; i++)
    {
        uint16_t v = src[i];
        if (v < mn) mn = v;
        if (v > mx) mx = v;
        pcm[i] = (int16_t)((int32_t)v - 32768);   /* 0..65535 -> signed, mic bias ~ VDD/2 ~ 0 */
    }
    adcMin[ch] = mn;
    adcMax[ch] = mx;

    adcReady[half] |= (uint8_t)(1U << ch);
    if (adcReady[half] != 3U) return;             /* wait for the other mic */
    adcReady[half] = 0U;
    adcCount++;

    Audio_ProcessBlock(MIC_SRC_ADC, NULL, adcPcm[half][0], adcPcm[half][1], 1U);
}

/* Fired by the HAL SAI IRQ handler when the first half of micRxBuffer is full */
void HAL_SAI_RxHalfCpltCallback(SAI_HandleTypeDef *hsai)
{
    if (hsai->Instance == hsai_BlockA1.Instance)
    {
        Audio_SaiBlock(&micRxBuffer[0]);
    }
}

/* Fired when the second half of micRxBuffer is full */
void HAL_SAI_RxCpltCallback(SAI_HandleTypeDef *hsai)
{
    if (hsai->Instance == hsai_BlockA1.Instance)
    {
        Audio_SaiBlock(&micRxBuffer[I2S_HALF_SAMPLES]);

        /* Toggle LD1 to show audio is flowing */
        HAL_GPIO_TogglePin(GPIOB, GPIO_PIN_0);
    }
}

/* Fired by the BDMA / DMA1 IRQ handler when the first half of an ADC buffer is full */
void HAL_ADC_ConvHalfCpltCallback(ADC_HandleTypeDef *hadc)
{
    if (hadc->Instance == ADC3)
    {
        Audio_AdcBlock(0U, 0U, &adcRxBuffer[0]);
    }
    else if (hadc->Instance == ADC2)
    {
        Audio_AdcBlock(1U, 0U, &adc2RxBuffer[0]);
    }
}

/* Fired when the second half of an ADC buffer is full */
void HAL_ADC_ConvCpltCallback(ADC_HandleTypeDef *hadc)
{
    if (hadc->Instance == ADC3)
    {
        Audio_AdcBlock(0U, 1U, &adcRxBuffer[ADC_HALF_SAMPLES]);
    }
    else if (hadc->Instance == ADC2)
    {
        Audio_AdcBlock(1U, 1U, &adc2RxBuffer[ADC_HALF_SAMPLES]);
    }
}

void HAL_ADC_ErrorCallback(ADC_HandleTypeDef *hadc)
{
    errAdc = 1U;                        /* never print (blocking) from an interrupt */
}

/**
 * @brief  Busy-wait until the I2S TX DMA is in the middle of a half-buffer.
 *         A source started right after this delivers its blocks half a block
 *         away from the TX half switch, and stays there (common PLL1 clock).
 */
static void Audio_WaitTxMidHalf(void)
{
    uint32_t pos;
    do
    {
        pos = __HAL_DMA_GET_COUNTER(hi2sOut.hdmatx) % I2S_HALF_SAMPLES;
    } while ((pos < I2S_HALF_SAMPLES / 2U - 16U) || (pos > I2S_HALF_SAMPLES / 2U + 16U));
}

/**
 * @brief  Reconfigure an ADC for audio: TIM6-triggered at fs, circular DMA, 16 bit, 8x oversampling.
 *         Kernel clock 80 MHz / 4 / 2 = 10 MHz (rev. V silicon halves it internally): one sample takes
 *         8 x (16.5 + 8.5) cycles = 20 us, which must stay below 1/fs = 22.7 us or triggers are skipped.
 *         Used for ADC3 (PF6, channel 8) and ADC2 (PA3, channel 15).
 */
static void Audio_ADC_Config(ADC_HandleTypeDef *hadc, uint32_t channel)
{
    ADC_ChannelConfTypeDef ch = {0};

    hadc->Init.ClockPrescaler           = ADC_CLOCK_ASYNC_DIV4;           /* PLL2P 80 MHz / 4 (/2 rev.V) */
    hadc->Init.Resolution               = ADC_RESOLUTION_16B;
    hadc->Init.ContinuousConvMode       = DISABLE;
    hadc->Init.ExternalTrigConv         = ADC_EXTERNALTRIG_T6_TRGO;
    hadc->Init.ExternalTrigConvEdge     = ADC_EXTERNALTRIGCONVEDGE_RISING;
    hadc->Init.ConversionDataManagement = ADC_CONVERSIONDATA_DMA_CIRCULAR;
    hadc->Init.Overrun                  = ADC_OVR_DATA_OVERWRITTEN;
    hadc->Init.OversamplingMode         = ENABLE;
    hadc->Init.Oversampling.Ratio                 = 8;
    hadc->Init.Oversampling.RightBitShift         = ADC_RIGHTBITSHIFT_3;
    hadc->Init.Oversampling.TriggeredMode         = ADC_TRIGGEREDMODE_SINGLE_TRIGGER;
    hadc->Init.Oversampling.OversamplingStopReset = ADC_REGOVERSAMPLING_CONTINUED_MODE;
    if (HAL_ADC_Init(hadc) != HAL_OK) Error_Handler();

    ch.Channel      = channel;
    ch.Rank         = ADC_REGULAR_RANK_1;
    ch.SamplingTime = ADC_SAMPLETIME_16CYCLES_5;
    ch.SingleDiff   = ADC_SINGLE_ENDED;
    ch.OffsetNumber = ADC_OFFSET_NONE;
    if (HAL_ADC_ConfigChannel(hadc, &ch) != HAL_OK) Error_Handler();

    if (HAL_ADCEx_Calibration_Start(hadc, ADC_CALIB_OFFSET_LINEARITY, ADC_SINGLE_ENDED) != HAL_OK)
        Error_Handler();
}

/**
 * @brief  Configure SAI1 Block A for the PCM1808 (slave, I2S, MD0/MD1/FMT = GND):
 *         master RX, 16 bit data in 32 bit slots (top 16 of the 24 PCM1808 bits) and the
 *         256 x fs master clock on PE2 = PCM1808 SCKI. Set here as well as in CubeMX so that a
 *         regenerated sai.c cannot turn the block back into a transmitter.
 */
static void Audio_SAI_Config(void)
{
    hsai_BlockA1.Init.AudioMode = SAI_MODEMASTER_RX;
    hsai_BlockA1.Init.MckOutput = SAI_MCK_OUTPUT_ENABLE;
    if (HAL_SAI_InitProtocol(&hsai_BlockA1, SAI_I2S_STANDARD, SAI_PROTOCOL_DATASIZE_16BITEXTENDED, 2) != HAL_OK)
    {
        Error_Handler();
    }

    /* The generated pin setup uses the low speed class, too slow for the 11.29 MHz MCLK: the output pins to the
     * PCM1808 (PE2, PE4, PE5) get the fastest edges; PE6 (DOUT) is an input. */
    GPIO_InitTypeDef io = {0};
    io.Pin       = GPIO_PIN_2 | GPIO_PIN_4 | GPIO_PIN_5;
    io.Mode      = GPIO_MODE_AF_PP;
    io.Pull      = GPIO_NOPULL;
    io.Speed     = GPIO_SPEED_FREQ_VERY_HIGH;
    io.Alternate = GPIO_AF6_SAI1;
    HAL_GPIO_Init(GPIOE, &io);
}

/**
 * @brief  TIM6 as ADC trigger at exactly the I2S/SAI sample rate.
 *         fs = PLL1Q / 256 and the timer clock also comes from PLL1, so
 *         ARR = timclk * 256 / PLL1Q (= 1600 here) gives zero drift.
 */
static void Audio_TIM6_Config(void)
{
    PLL1_ClocksTypeDef pll;
    HAL_RCCEx_GetPLL1ClockFreq(&pll);
    uint32_t timClk = 2U * HAL_RCC_GetPCLK1Freq();                        /* APB1 prescaler 4 -> x2 */
    uint32_t div    = (uint32_t)(((uint64_t)timClk * 256U + pll.PLL1_Q_Frequency / 2U)
                                 / pll.PLL1_Q_Frequency);

    __HAL_RCC_TIM6_CLK_ENABLE();
    TIM6->CR1 = 0;
    TIM6->PSC = 0;
    TIM6->ARR = div - 1U;
    TIM6->EGR = TIM_EGR_UG;             /* load PSC/ARR */
    TIM6->CR2 = TIM_CR2_MMS_1;          /* TRGO on update event */
}

void HAL_I2S_TxCpltCallback(I2S_HandleTypeDef *hi2s)
{
    if (hi2s->Instance == hi2sOut.Instance) { txCount++; }
}

void HAL_SAI_ErrorCallback(SAI_HandleTypeDef *hsai)
{
    errSai = 1U;
}

void HAL_I2S_ErrorCallback(I2S_HandleTypeDef *hi2s)
{
    errI2s = 1U;
}

static float Audio_Db(float lin)
{
    return (lin > 1e-9f) ? 20.0f * log10f(lin) : -200.0f;
}

/* LD2 (yellow): room adaptation running */
static void Room_ShowAdapt(void)
{
    HAL_GPIO_WritePin(GPIOE, GPIO_PIN_1, (RoomEq_GetAdapt() || adaptPending) ? GPIO_PIN_SET : GPIO_PIN_RESET);
}

/* Run / freeze, both with a marker (1 pulse = run, 2 pulses = freeze). A start waits until the marker has faded
 * out, then Room_AdaptPoll() starts the adaptation. */
static void Room_ToggleAdapt(void)
{
    if (RoomEq_GetAdapt() || adaptPending)
    {
        adaptPending = 0U;
        RoomEq_SetAdapt(0);
        markerReq = 2U;
        UART_Print("Room adaptation: FROZEN (equalizer kept), marker: 2 pulses\r\n");
    }
    else
    {
        markerReq    = 1U;
        adaptStartAt = HAL_GetTick() + MARKER_BURST_MS + MARKER_SETTLE_MS;
        adaptPending = 1U;
        UART_Print("Room adaptation: RUNNING (LD2 lit), marker: 1 pulse, adaptation starts after it\r\n");
    }
    Room_ShowAdapt();
}

static void Room_AdaptPoll(void)
{
    if (adaptPending && (int32_t)(HAL_GetTick() - adaptStartAt) >= 0)
    {
        adaptPending = 0U;
        RoomEq_SetAdapt(1);
    }
}

/* Mute the output for 0.8 s: the reference is silent, the mics hear only their noise and the room analysis
 * learns the noise floor per band (bands that are not heard clearly above it are not adapted). */
static void Room_StartCal(void)
{
    RoomEq_ForgetNoiseFloor();
    muteUntil = HAL_GetTick() + 800U;
    roomMute  = 1U;
    UART_Print("Measuring the mic noise floor: output muted for 0.8 s\r\n");
}

/* room equalizer on / off for an A/B comparison (the adaptation keeps running) */
static void Room_ToggleBypass(void)
{
    roomReset = 1U;
    roomBypass = (uint8_t)!roomBypass;
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_14, roomBypass ? GPIO_PIN_SET : GPIO_PIN_RESET);       /* LD3 red lit = room EQ off */
    UART_Print(roomBypass ? "Room equalizer: OFF - clean input (LD3 lit)\r\n" : "Room equalizer: ON\r\n");
}

/* rebuild the manual filter coefficients from the slots and hand them to the audio interrupt */
static void Manual_Update(void)
{
    const uint32_t idle = 1U - manualCur;
    uint32_t n = 0;
    for (uint32_t i = 0; i < ROOM_MANUAL_MAX; i++)
        if (manualPk[i].on && fabsf(manualPk[i].gainDb) >= 0.05f)
            RoomEq_PeakCoefs((double)manualPk[i].freq, (double)manualPk[i].gainDb, (double)manualPk[i].q, &manualBuf[idle][n++]);
    manualCount[idle] = n;
    manualCur = idle;
    manualSeq = manualSeq + 1U;
}

static void Manual_Print(void)
{
    char m[100];
    for (uint32_t i = 0; i < ROOM_MANUAL_MAX; i++)
    {
        snprintf(m, sizeof(m), "%cmanual %u: %-3s %7.1f Hz  %+5.1f dB  Q %4.1f\r\n", (i == manualSel) ? '>' : ' ', (unsigned)(i + 1U),
                 manualPk[i].on ? "ON" : "off", (double)manualPk[i].freq, (double)manualPk[i].gainDb, (double)manualPk[i].q);
        UART_Print(m);
    }
}

/* k = next slot, x/X = frequency -/+ 0.5 Hz, j/J = gain -/+ 0.5 dB, l/L = Q smaller/larger, o = slot on/off */
static void Manual_Key(char c)
{
    ManualPk *p = &manualPk[manualSel];
    switch (c)
    {
        case 'k': manualSel = (manualSel + 1U) % ROOM_MANUAL_MAX; Manual_Print(); return;
        case 'x': p->freq -= 0.5f; break;
        case 'X': p->freq += 0.5f; break;
        case 'j': p->gainDb -= 0.5f; break;
        case 'J': p->gainDb += 0.5f; break;
        case 'l': p->q /= 1.15f; break;
        case 'L': p->q *= 1.15f; break;
        case 'o': p->on = (uint8_t)!p->on; break;
        default: return;
    }
    if (p->freq < 20.0f)  p->freq = 20.0f;
    if (p->freq > 500.0f) p->freq = 500.0f;
    if (p->gainDb < -24.0f) p->gainDb = -24.0f;
    if (p->gainDb >  12.0f) p->gainDb =  12.0f;
    if (p->q < 0.5f)  p->q = 0.5f;
    if (p->q > 30.0f) p->q = 30.0f;
    Manual_Update();
    Manual_Print();
}

static void Room_PrintState(void)
{
    char m[220];
    snprintf(m, sizeof(m), "Room EQ: adapt=%s eq=%s filters=%u frames=%lu noise floor=%s ref=%.0f mic1=%.0f mic2=%.0f LSB rms\r\n",
             RoomEq_GetAdapt() ? "run" : "frozen", roomBypass ? "OFF" : "on", (unsigned)ROOMEQ_MAX_FILTERS,
             (unsigned long)RoomEq_Frames(), RoomEq_NoiseFloorKnown() ? "known" : "NOT measured",
             (double)RoomEq_RefRms(), (double)RoomEq_MicRms(0U), (double)RoomEq_MicRms(1U));
    UART_Print(m);

    int n = snprintf(m, sizeof(m), "band Hz :");
    for (uint32_t b = 0; b < ROOMEQ_BANDS; b++) n += snprintf(&m[n], sizeof(m) - (size_t)n, "%6.0f", RoomEq_BandCenter(b));
    UART_Print(m); UART_Print("\r\n");
    n = snprintf(m, sizeof(m), "ref dB  :");                    /* reference level re its strongest band */
    for (uint32_t b = 0; b < ROOMEQ_BANDS; b++) n += snprintf(&m[n], sizeof(m) - (size_t)n, "%6.0f", (double)RoomEq_RefRelDb(b));
    UART_Print(m); UART_Print("\r\n");
    for (uint32_t r = 0; r < ROOMEQ_MICS; r++)                  /* mic SNR over its noise floor, '-' = band NOT used */
    {
        n = snprintf(m, sizeof(m), "snr%u dB :", (unsigned)(r + 1U));
        for (uint32_t b = 0; b < ROOMEQ_BANDS; b++)
            n += snprintf(&m[n], sizeof(m) - (size_t)n, "%5.0f%c", (double)RoomEq_BandSnrDb(r, b), RoomEq_BandValid(r, b) ? ' ' : '-');
        UART_Print(m); UART_Print("\r\n");
    }
    for (uint32_t r = 0; r < ROOMEQ_MICS; r++)
    {
        n = snprintf(m, sizeof(m), "mic%u dB :", (unsigned)(r + 1U));
        for (uint32_t b = 0; b < ROOMEQ_BANDS; b++) n += snprintf(&m[n], sizeof(m) - (size_t)n, "%+6.1f", (double)RoomEq_Weight(r, b));
        UART_Print(m); UART_Print("\r\n");
    }
    n = snprintf(m, sizeof(m), "filter Hz:");
    for (uint32_t i = 0; i < ROOMEQ_MAX_FILTERS; i++) n += snprintf(&m[n], sizeof(m) - (size_t)n, "%6.0f", RoomEq_FilterFreq(i));
    UART_Print(m); UART_Print("\r\n");
    n = snprintf(m, sizeof(m), "gain dB  :");
    for (uint32_t i = 0; i < ROOMEQ_MAX_FILTERS; i++) n += snprintf(&m[n], sizeof(m) - (size_t)n, "%+6.1f", RoomEq_FilterGainDb(i));
    UART_Print(m); UART_Print("\r\n");
    Manual_Print();
}

/**
 * @brief  Control from the ST-LINK serial terminal (USART3, 115200), non-blocking, one key per call.
 *           '+' / '-'  PCM1808 gain +1 dB / -1 dB      ']' / '['  +0.1 dB / -0.1 dB
 *           'g'        print the gain                   'r'        reset the gain to MIC_GAIN_DB
 *           'a'        room adaptation run / freeze (same as a short B1 press, LD2 lit = running)
 *           'q'        room equalizer on / off (same as holding B1; LD3 red lit = off)
 *           'z'        forget the room estimate (equalizer flat)
 *           'k' 'x' 'X' 'j' 'J' 'l' 'L' 'o'   manual peaking filters: next slot, frequency -/+ 0.5 Hz, gain -/+ 0.5 dB,
 *                      Q smaller/larger, slot on/off (for narrow room modes, e.g. 84.5 Hz)
 *           'n'        measure the mic noise floor again (output muted for 0.8 s)
 *           'w'        print band weights, band validity (ref level, mic SNR) and filter gains
 *         The gain is kept until reset/power-off; copy it into MIC_GAIN_DB to make it permanent.
 */
static void Gain_HandleUart(void)
{
    if (__HAL_UART_GET_FLAG(&huart3, UART_FLAG_ORE)) __HAL_UART_CLEAR_OREFLAG(&huart3);
    if (!__HAL_UART_GET_FLAG(&huart3, UART_FLAG_RXNE)) return;

    char  c    = (char)(huart3.Instance->RDR & 0xFFU);
    float step = 0.0f;

    switch (c)
    {
        case '+': step =  1.0f; break;
        case '-': step = -1.0f; break;
        case ']': step =  0.1f; break;
        case '[': step = -0.1f; break;
        case 'r': srcGain[MIC_SRC_I2S] = powf(10.0f, MIC_GAIN_DB / 20.0f); break;
        case 'g': break;
        case 'a': Room_ToggleAdapt(); return;
        case 'q': Room_ToggleBypass(); return;
        case 'z':
            RoomEq_Reset();
            roomReset = 1U;
            UART_Print("Room estimate reset (equalizer flat)\r\n");
            return;
        case 'w': Room_PrintState(); return;
        case 'n': Room_StartCal(); return;
        case 'k': case 'x': case 'X': case 'j': case 'J': case 'l': case 'L': case 'o': Manual_Key(c); return;
        default:  return;
    }

    if (step != 0.0f)
    {
        float db = Audio_Db(srcGain[MIC_SRC_I2S]) + step;
        if (db < -40.0f) db = -40.0f;
        if (db >  60.0f) db =  60.0f;
        srcGain[MIC_SRC_I2S] = powf(10.0f, db / 20.0f);   /* single float store: safe vs. the ISRs */
    }

    char m[60];
    snprintf(m, sizeof(m), "Gain PCM1808 = %.1f dB\r\n", (double)Audio_Db(srcGain[MIC_SRC_I2S]));
    UART_Print(m);
}

/**
 * @brief  Copy the correction coefficients from flash into DTCM and clear the filter states.
 */
static void Eq_Init(void)
{
    memset(eqState, 0, sizeof(eqState));
    for (uint32_t k = 0; k < MIC_SRC_COUNT; k++)
    {
        for (uint32_t c = 0; c < 2U; c++)
        {
            memcpy(eqCoef[k][c], eqTable[k][c].bq, eqTable[k][c].n * sizeof(MicEqBiquad));
        }
    }
}

/**
 * @brief  Blocking UART print helper over USART3
 */
void UART_Print(char *str)
{
    HAL_UART_Transmit(&huart3, (uint8_t *)str, strlen(str), HAL_MAX_DELAY);
}
